public class Hello {
    public static void main(String[] args) {
        System.out.println("Hello");
    }
}

public class Student {
    private String name;
    public String getName() { return name; }
}

class Dog {
    String name;
    void bark() { System.out.println("汪汪"); }
}

interface Runnable2 {
    void run();
}
class MyTask implements Runnable2 {
    public void run() { /* 具体实现 */ }
}

abstract class Shape {
    abstract double area();
}

class MathUtil {
    static int add(int a, int b) { return a + b; }
}
// 调用：MathUtil.add(1, 2)

if (score >= 60) {
    System.out.println("及格");
} else {
    System.out.println("不及格");
}

if (age >= 18) {
    System.out.println("成年");
} else {
    System.out.println("未成年");
}

switch (day) {
    case 1: System.out.println("周一"); break;
    default: System.out.println("其他");
}

for (int i = 0; i < 10; i++) {
    if (i == 5) break;  // 到 5 就停
}

for (int i = 1; i <= 10; i++) {
    if (i % 2 == 0) continue;  // 跳过偶数
    System.out.println(i);
}

int max(int a, int b) {
    return a > b ? a : b;
}

public void setName(String name) {
    this.name = name;  // this.name 是成员变量
}

class Student extends Person {
    // Student 自动拥有 Person 的公开成员
}

class Cat implements Animal {
    public void speak() { System.out.println("喵"); }
}

try {
    int r = 10 / 0;
} catch (ArithmeticException e) {
    System.out.println("除数不能为 0");
}

if (age < 0) {
    throw new IllegalArgumentException("年龄不能为负");
}

void readFile(String path) throws IOException {
    Files.readAllLines(Path.of(path));
}

if (obj instanceof String s) {
    System.out.println(s.length());  // 模式匹配，Java 16+
}

int day = switch (d) {
    case 1 -> 1;
    default -> yield 0;
};
